Method.Implementation:

	$$$TRACE("JMSinboundAdapter OnInit "  _ ..JmsUrl)
	$$$TRACE("JmsGateway: " _ $IsObject(..JmsGateway) _ ", ActMqObj:" _$IsObject(..ActMqObj))
	$$$TRACE("Is connected: " _ ..connected _ ", Attept # " _ ..RetryCnt _ ", Max: " _  ..NumberOfRetries)

	Set tStat = $$$OK


	 SET localhost=$SYSTEM.INetInfo.LocalHostName()            /* get host name */
     $$$TRACE("Component: " _ ..BusinessHost.%ConfigName _ " in " _$NAMESPACE _", local host name is " _ localhost)

	// get an instance of JMSGateway and connect to JMSGateway Super Server
	try {
		if ((..connected = 0) && (..RetryCnt <= ..NumberOfRetries))
		{
			set ..RetryCnt = ..RetryCnt + 1
			if ($L(..JMSJarPath) = 0)
			{
			   	SET mygenex = ##class(%Exception.General).%New("JMSJarPath does not have class path for jar files ")
	    		throw mygenex

			}
			Set ..JmsGateway=##class(EnsLib.JavaGateway.JavaGateway).%New()
			Set classPath=##class(%ListOfDataTypes).%New()

			Do classPath.Insert(..JMSJarPath)
			$$$TRACE("JMS Call Path added: " _ ..JMSJarPath)

			$$$TRACE("Trying to connect: " _ ..JavaGateWayHost _ ":" _ ..JavaGateWayPort _ ", attempt #: " _ ..RetryCnt)

			Set tStat=..JmsGateway.%Connect(..JavaGateWayHost,..JavaGateWayPort,$NAMESPACE,5,classPath) 
			If 'tStat 
			{
				set tStat = $$$ISERR(tStat)
				set exp = ##class(%Exception.General).%New()
				set exp.Code = tStat.Name
				set exp.Data = tStat.Data
				set exp.Name = "Java Gateway connection error: " _ ..JavaGateWayHost _ ", " _ ..JavaGateWayPort
				Throw exp  
			}
			$$$TRACE("Connected to Java Gateway")
			Set listArray = ##class(%ListOfDataTypes).%New()
			Set p=1
			For {
				Set piece=$P(..JMSJarPath,":",p)
				Quit:piece=""
				do listArray.Insert(piece)
				set p = p+1
				$$$TRACE("Jar file: " _ piece)
			}

			Set status=..JmsGateway.%Import("IHC.ITF.ITFCOMMON.JMS.ActiveMQ.ActiveMQClass", .classes, listArray) 
			If 'tStat 
			{
				set tStat = $$$ISERR(tStat)
				set exp = ##class(%Exception.General).%New()
				set exp.Code = tStat.Name
				set exp.Data = tStat.Data
				set exp.Name = "Java Gateway import error: " _ ..JavaGateWayHost _ ", " _ ..JavaGateWayPort
				Throw exp
			}
			$$$TRACE("Imported Jar, creating class to connect to " _ ..QueueName)
			set ..ActMqObj = ##class(IHC.ITF.ITFCOMMON.JMS.ActiveMQ.ActiveMQClass).%New(..JmsGateway, ..JmsUrl, ..QueueName)

			$$$TRACE("Created class IHC.ITF.ITFCOMMON.JMS.ActiveMQ.ActiveMQClass: " _ ..JmsUrl _ ", " _ ..QueueName)
			$$$TRACE("JmsGateway: " _ $IsObject(..JmsGateway) _ ", ActMqObj:" _$IsObject(..ActMqObj))

			Do ..ActMqObj.CreateConsumer()

			Set ..connected = 1
			set ..RetryCnt = 0
		}
		else
		{
			    Set tSC=$$$ERROR($$$GeneralError, "Failed to connect to JMS server after " _ ..NumberOfRetries _ " tries")
		}
	} catch err
     {

	     if $GET(%objlasterror) '= ""
	    {
	        set errMsg =  $System.Status.GetErrorText(%objlasterror)
	    }
	    else
	    {
		    set errMsg = "No objlasterror"
	    }
   	    Set tSC=$$$ERROR($$$GeneralError, "OnInit : " _ err.Name _ " / Location:" _ err.Location _ " / Data: " _err.Data _ " " _ errMsg)

	    if (..RetryCnt >=  ..NumberOfRetries)
	    {
	    	set alert = ##class(Ens.AlertRequest).%New()
	    	set alert.AlertText = "Exception in OnInit: Name: " _ err.Name _ " / Location:" _ err.Location _ " / Data: " _err.Data _ " / Details: " _ errMsg
	    	set alert.SourceConfigName = ..BusinessHost.%ConfigName
	    	do ..BusinessHost.SendAlert(alert)

	    	SET mygenex = ##class(%Exception.General).%New("Tried to connect for " _ ..NumberOfRetries _ " times to Gateway: "_ ..JavaGateWayHost _", " _ ..JavaGateWayPort _ ", JMS:" _ ..JmsUrl)
	    	throw mygenex
	     }

	    if ((..connected = 1) && ($IsObject(..ActMqObj)) )
		{
				Do ..ActMqObj.CloseActiveMQ()
				set ..ActMqObj = $$$NULLOREF

		}

	    if ((..connected = 1) &&  ($IsObject(..JmsGateway)) )
	    {
		  	    Do ..JmsGateway.%Disconnect()
		  	    set ..JmsGateway = $$$NULLOREF

	    }

    }		

	Quit tStat

	Set tStat = $$$OK

	if ( ..connected = 0)
	{
		set tStat = ..OnInit()
	}
	if ( ..connected = 0 )
	{
		Set tStat = $$$ERROR($$$GeneralError, "Can not connect to JMS server: " _ tStat)
	}
	else
	{
		try {
        	$$$TRACE("OnTask: receive message")
        	set msg = ..ActMqObj.recvMsg()
        	do {

				if ($L(msg) = 0)
				{
	    			 $$$TRACE("No message in the queue")
	    		 	Quit 
    			}
   				else
				{
	   				$$$TRACE("Got a Message " )
	   				Set tStat = ..SendMessageToService(msg)	   
				}

				$$$TRACE("receive without timeout")
    			set msg = ..ActMqObj.recvMsg()
        	} while ($L(msg) '= 0)

		 } catch err
    	 {
	    	 if $GET(%objlasterror) '= ""
	    	{
	        	set errMsg =  $System.Status.GetErrorText(%objlasterror)
	    	}
	    	else
		    {
			    set errMsg = "No error obj"
	    	}
	    	Set tSC=$$$ERROR($$$GeneralError, err.Name _ " / Location:" _ err.Location _ " / Data: " _err.Data _ " " _ errMsg)

	   		if ((..connected = 1) && ($IsObject(..ActMqObj)) )
			{
				Do ..ActMqObj.CloseActiveMQ()
				set ..ActMqObj = $$$NULLOREF
				$$$TRACE("CloseActiveMQ")
			}

	 		if ((..connected = 1) && ($IsObject(..JmsGateway)) )
	    	{
		  		    Do ..JmsGateway.%Disconnect()
		  		    set ..JmsGateway = $$$NULLOREF
		  	    	$$$TRACE("JmsGateway.%Disconnect")
	    	}
	    	Set ..connected = 0
    	}
	}

	Quit tStat

$$$TRACE("JMSinboundAdapter OnTearDown")
if ((..connected = 1) && ($IsObject(..ActMqObj)) )
	{
			Do ..ActMqObj.CloseActiveMQ()
			set ..ActMqObj = $$$NULLOREF
			$$$TRACE("CloseActiveMQ")
	}

if ((..connected = 1) && ($IsObject(..JmsGateway)) )
{
	  	    Do ..JmsGateway.%Disconnect()
	  	    set ..JmsGateway = $$$NULLOREF
	  	    $$$TRACE("JmsGateway.%Disconnect")
}
Set ..connected = 0
Quit $$$OK
